# ===========================================================================
#  Zone1V1.map  --  route-planning sheet for AI_NAV.c
#  A flat 5000 x 4000 m coordinate sheet (x = east, y = north, origin lower-left).
#  It does not represent a real place; it is a test arena for the planner.
#
#  Keywords (one per line, '#' starts a comment, names have no spaces):
#    MAP            name width height
#    MARGIN         metres of clearance kept around every no-fly zone
#    LINK           longest straight hop the planner will try between two nodes
#    NODE           name x y alt            (cruise altitude in metres)
#    NOFLY_CIRCLE   name cx cy r            (hard constraint)
#    NOFLY_BOX      name x0 y0 x1 y1        (hard constraint)
#    HAZARD_CIRCLE  name cx cy r mult       (soft weight: cost x mult inside)
#    HAZARD_BOX     name x0 y0 x1 y1 mult
#    CORRIDOR       nodeA nodeB mult        (preferred lane: mult < 1 is cheaper)
#    START / END    name                    (defaults if none given on the command line)
# ===========================================================================

MAP     Zone1V1 5000 4000
MARGIN  120
LINK    1500

# ------------------------------- nodes ------------------------------------
#        name    x     y     alt
NODE     HOME    300   300   100
NODE     N02     800   900   110
NODE     N03     700   1800  110
NODE     N04     400   2800  120
NODE     N05     1300  400   100
NODE     N06     1500  1300  120
NODE     N07     1400  2300  130
NODE     N08     1200  3400  120
NODE     N09     2200  700   110
NODE     N10     2450  1950  130
NODE     N11     2300  2700  140
NODE     N12     2100  3600  130
NODE     N13     3100  400   100
NODE     N14     3200  1200  120
NODE     N15     3300  2200  140
NODE     N16     3000  3500  140
NODE     N17     3700  3800  130
NODE     N18     4000  700   110
NODE     N19     4100  1700  130
NODE     N20     4200  2700  140
NODE     N21     4300  3600  120
NODE     DEPOT   4700  3500  110
NODE     N23     4600  600   100
NODE     N24     3700  2500  140
NODE     N25     2850  1650  130
NODE     N26     1800  1900  130

# --------------------- no-fly zones (hard constraints) --------------------
NOFLY_CIRCLE  Airfield     2300  1250  400
NOFLY_CIRCLE  Substation   3300  2900  300
NOFLY_CIRCLE  Stadium      4000  2200  250
NOFLY_CIRCLE  Mast         1400  3000  200
NOFLY_BOX     Reservoir    700   1100  1100  1500

# --------------------- hazard zones (soft weights) ------------------------
HAZARD_CIRCLE Ridge        1900  2500  450  3.0
HAZARD_CIRCLE Town         3600  1500  500  2.5
HAZARD_CIRCLE Thermals     2800  450   500  1.8
HAZARD_CIRCLE Crowd        4400  3200  350  4.0

# --------------- preferred air corridors (cheaper to fly) -----------------
CORRIDOR HOME N05  0.80
CORRIDOR N05  N09  0.80
CORRIDOR N09  N13  0.80
CORRIDOR N13  N18  0.80
CORRIDOR N18  N23  0.80
CORRIDOR N04  N08  0.85
CORRIDOR N08  N12  0.85
CORRIDOR N12  N16  0.85
CORRIDOR N16  N17  0.85
CORRIDOR N17  N21  0.85
CORRIDOR N21  DEPOT 0.85
CORRIDOR N19  N20  0.90
CORRIDOR N20  N21  0.90

START HOME
END   DEPOT
